func (db *DeploymentBuilder) applyDeploymentSpecModifications(
	deployment *appsv1.Deployment,
	accessStrategy *workspacev1alpha1.WorkspaceAccessStrategy,
) error {
	if deployment == nil {
		return fmt.Errorf("deployment cannot be nil")
	}
	if accessStrategy.Spec.DeploymentModifications == nil {
		return nil // Nothing to do
	}

	mods := accessStrategy.Spec.DeploymentModifications

	// Add volumes
	if mods.PodModifications != nil && len(mods.PodModifications.Volumes) > 0 {
		logf.Log.V(1).Info("Adding volumes from deployment modifications",
			"accessStrategy", accessStrategy.Name,
			"volumeCount", len(mods.PodModifications.Volumes))

		deployment.Spec.Template.Spec.Volumes = append(
			deployment.Spec.Template.Spec.Volumes,
			mods.PodModifications.Volumes...,
		)

		for _, volume := range mods.PodModifications.Volumes {
			logf.Log.V(1).Info("Added volume",
				"accessStrategy", accessStrategy.Name,
				"volumeName", volume.Name)
		}
	}

	// Add volume mounts to primary container
	if mods.PodModifications != nil &&
		mods.PodModifications.PrimaryContainerModifications != nil &&
		len(mods.PodModifications.PrimaryContainerModifications.VolumeMounts) > 0 {

		if len(deployment.Spec.Template.Spec.Containers) == 0 {
			return fmt.Errorf("no containers found in deployment to add volume mounts")
		}

		logf.Log.V(1).Info("Adding volume mounts to primary container",
			"accessStrategy", accessStrategy.Name,
			"mountCount", len(mods.PodModifications.PrimaryContainerModifications.VolumeMounts))

		primaryContainer := &deployment.Spec.Template.Spec.Containers[0]
		primaryContainer.VolumeMounts = append(
			primaryContainer.VolumeMounts,
			mods.PodModifications.PrimaryContainerModifications.VolumeMounts...,
		)

		for _, mount := range mods.PodModifications.PrimaryContainerModifications.VolumeMounts {
			logf.Log.V(1).Info("Added volume mount to primary container",
				"accessStrategy", accessStrategy.Name,
				"volumeName", mount.Name,
				"mountPath", mount.MountPath)
		}
	}

	// Add init containers
	if mods.PodModifications != nil && len(mods.PodModifications.InitContainers) > 0 {
		logf.Log.V(1).Info("Adding init containers",
			"accessStrategy", accessStrategy.Name,
			"containerCount", len(mods.PodModifications.InitContainers))

		deployment.Spec.Template.Spec.InitContainers = append(
			deployment.Spec.Template.Spec.InitContainers,
			mods.PodModifications.InitContainers...,
		)

		for _, container := range mods.PodModifications.InitContainers {
			logf.Log.V(1).Info("Added init container",
				"accessStrategy", accessStrategy.Name,
				"containerName", container.Name,
				"image", container.Image)
		}
	}

	// Add additional containers
	if mods.PodModifications != nil && len(mods.PodModifications.AdditionalContainers) > 0 {
		logf.Log.V(1).Info("Adding additional containers",
			"accessStrategy", accessStrategy.Name,
			"containerCount", len(mods.PodModifications.AdditionalContainers))

		deployment.Spec.Template.Spec.Containers = append(
			deployment.Spec.Template.Spec.Containers,
			mods.PodModifications.AdditionalContainers...,
		)

		for _, container := range mods.PodModifications.AdditionalContainers {
			logf.Log.V(1).Info("Added additional container",
				"accessStrategy", accessStrategy.Name,
				"containerName", container.Name,
				"image", container.Image)
		}
	}

	logf.Log.V(1).Info("Successfully applied deployment modifications",
		"accessStrategy", accessStrategy.Name)

	return nil
}]

[Method EnsureAccessResourcesExist @ internal/controller/resource_manager_access.go:60-132 | func (rm *ResourceManager) EnsureAccessResourcesExist(
func (rm *ResourceManager) EnsureAccessResourcesExist(
	ctx context.Context,
	workspace *workspacev1alpha1.Workspace,
	accessStrategy *workspacev1alpha1.WorkspaceAccessStrategy,
	service *corev1.Service,
) error {
	logger := logf.FromContext(ctx)
	// The AccessResource MUST be in the Workspace namespace
	// in order for the Workspace is the owner of the AccessResource
	accessResourceNamespace := workspace.Namespace

	// Track which resources are defined in the current AccessStrategy
	currentResources := make(map[string]bool)

	// ensure each of the resources defined in the accessStrategy exists
	for _, resourceTemplate := range accessStrategy.Spec.AccessResourceTemplates {
		// Build the lookup name that will be stored in status
		lookupName := fmt.Sprintf("%s-%s", resourceTemplate.NamePrefix, workspace.Name)
		// Track this resource as defined in the current AccessStrategy
		resourceKey := fmt.Sprintf("%s/%s/%s", resourceTemplate.Kind, lookupName, accessResourceNamespace)
		currentResources[resourceKey] = true

		// Apply resource
		err := rm.ensureAccessResourceExists(ctx, workspace, accessStrategy, service, &resourceTemplate, accessResourceNamespace)
		if err != nil {
			return err
		}
	}

	// Check for resources that exist in status but are no longer in the AccessStrategy
	// These need to be cleaned up
	var resourcesToDelete []workspacev1alpha1.AccessResourceStatus
	var resourcesToKeep []workspacev1alpha1.AccessResourceStatus

	for _, resource := range workspace.Status.AccessResources {
		resourceKey := fmt.Sprintf("%s/%s/%s", resource.Kind, resource.Name, resource.Namespace)
		if !currentResources[resourceKey] {
			// This resource is no longer in the AccessStrategy, mark for deletion
			resourcesToDelete = append(resourcesToDelete, resource)
			logger.Info("Found access resource to delete (no longer in AccessStrategy)",
				"kind", resource.Kind,
				"name", resource.Name,
				"namespace", resource.Namespace)
		} else {
			// Keep resources that are still in the AccessStrategy
			resourcesToKeep = append(resourcesToKeep, resource)
		}
	}

	// Delete resources that are no longer in the AccessStrategy
	resourcesDeleted := false
	for _, resource := range resourcesToDelete {
		resourceCopy := resource // Create a copy to avoid pointer issues in the loop
		removed, err := rm.ensureAccessResourceDeleted(ctx, &resourceCopy)
		if err != nil {
			return fmt.Errorf("failed to delete removed access resource: %w", err)
		}
		if removed {
			resourcesDeleted = true
			logger.Info("Deleted access resource that was removed from AccessStrategy",
				"kind", resourceCopy.Kind,
				"name", resourceCopy.Name,
				"namespace", resourceCopy.Namespace)
		}
	}

	// Only update the status array if resources were actually deleted
	if resourcesDeleted {
		workspace.Status.AccessResources = resourcesToKeep
	}

	return nil
}, Method BuildUnstructuredResource @ internal/controller/access_resources_builder.go:40-124 | func (b *AccessResourcesBuilder) BuildUnstructuredResource(
func (b *AccessResourcesBuilder) BuildUnstructuredResource(
	accessResourceTemplate workspacev1alpha1.AccessResourceTemplate,
	workspace *workspacev1alpha1.Workspace,
	accessStrategy *workspacev1alpha1.WorkspaceAccessStrategy,
	service *corev1.Service,
) (*unstructured.Unstructured, error) {
	// Generate resource name using NamePrefix and workspace name
	name := fmt.Sprintf("%s-%s", accessResourceTemplate.NamePrefix, workspace.Name)

	// Process resource template
	resourceTmpl, err := template.New("resource").Funcs(template.FuncMap{
		"b32encode": workspaceutil.EncodeNamespaceB32,
	}).Parse(accessResourceTemplate.Template)
	if err != nil {
		return nil, fmt.Errorf("failed to parse resource template: %w", err)
	}

	accessResourceData := &fullAccessResourceData{
		Workspace:      workspace,
		AccessStrategy: accessStrategy,
		Service:        service,
	}

	var resourceBuffer bytes.Buffer
	if err := resourceTmpl.Execute(&resourceBuffer, accessResourceData); err != nil {
		return nil, fmt.Errorf("failed to execute resource template: %w", err)
	}
	resourceYAML := resourceBuffer.String()

	// First add apiVersion and kind to the YAML
	yamlWithMeta := fmt.Sprintf("apiVersion: %s\nkind: %s\n%s",
		accessResourceTemplate.ApiVersion,
		accessResourceTemplate.Kind,
		resourceYAML)

	// Convert YAML to unstructured.Unstructured
	obj := &unstructured.Unstructured{}
	if err := yaml.Unmarshal([]byte(yamlWithMeta), obj); err != nil {
		return nil, fmt.Errorf("failed to unmarshal resource YAML: %w", err)
	}

	// Set basic metadata
	obj.SetName(name)

	// The AccessResource MUST be in the Workspace namespace
	// in order for the Workspace is the owner of the AccessResource
	targetNamespace := accessResourceData.Workspace.Namespace
	obj.SetNamespace(targetNamespace)

	// Set Group-Version-Kind properly by parsing the API version
	apiVersionParts := strings.Split(accessResourceTemplate.ApiVersion, "/")
	var group, version string
	if len(apiVersionParts) == 2 {
		group = apiVersionParts[0]
		version = apiVersionParts[1]
	} else {
		// Core API group uses version without group prefix
		version = accessResourceTemplate.ApiVersion
	}

	obj.SetGroupVersionKind(schema.GroupVersionKind{
		Group:   group,
		Version: version,
		Kind:    accessResourceTemplate.Kind,
	})

	// Add labels to the access resource referring to:
	// - the Workspace
	// - AccessStrategy
	labels := obj.GetLabels()
	if labels == nil {
		labels = make(map[string]string)
	}
	accessStrategyNamespace := accessStrategy.Namespace
	if accessStrategyNamespace == "" {
		accessStrategyNamespace = workspace.Namespace
	}
	labels[workspaceutil.LabelWorkspaceName] = workspace.Name
	labels[LabelWorkspaceNamespace] = workspace.Namespace
	labels[LabelAccessStrategyName] = accessStrategy.Name
	labels[LabelAccessStrategyNamespace] = accessStrategyNamespace
	obj.SetLabels(labels)

	return obj, nil
}]

