		})
	})
	defer maxDurationTimer.Stop()

	// Run bridge in a goroutine so we can select on context cancellation
	bridgeErr := make(chan error, 1)
	go func() {
		bridgeErr <- bridge.Run()
	}()

	select {
	case err := <-bridgeErr:
		return err
	case <-ctx.Done():
		// Context cancelled (max duration or external termination)
		_ = s.ws.Close()
		_ = tcp.Close()
		return ctx.Err()
	}
}

